//! Integration tests for the Bitwig `.bwproject` parser.
//!
//! Fixtures (generated by `fixtures/gen_bw_fixture.py`):
//!   - `test_project.bwproject` — 4 tracks, 3 locators, 128 BPM, embedded samples
//!   - `no_samples.bwproject`   — same project without a `samples/` folder

use clavus_parser_bw::BitwigParser;
use std::path::Path;

fn fixture_path() -> std::path::PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("../../../fixtures/test_project.bwproject")
}

fn no_samples_path() -> std::path::PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("../../../fixtures/no_samples.bwproject")
}

/// A temp file name that no other test — in this process or in any other
/// one — can collide with.
///
/// The name used to be a fixed string. Two test runs happening at once
/// (a `cargo test` and a pre-commit hook's `cargo test`, say) then wrote
/// the same file, and whichever finished first deleted it out from under
/// the other. The other one failed with "No such file or directory" and
/// looked like a parser bug. The process id and the clock make the name
/// unique across processes; the counter makes it unique within one.
fn unique_name(stem: &str) -> String {
    use std::sync::atomic::{AtomicU64, Ordering};
    use std::time::{SystemTime, UNIX_EPOCH};
    static CTR: AtomicU64 = AtomicU64::new(0);
    let n = CTR.fetch_add(1, Ordering::Relaxed);
    let nanos = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|d| d.as_nanos())
        .unwrap_or(0);
    format!("{}_{}_{}_{}", stem, std::process::id(), nanos, n)
}

/// A temp path for a throwaway `.bwproject`.
fn temp_path(stem: &str) -> std::path::PathBuf {
    std::env::temp_dir().join(format!("{}.bwproject", unique_name(stem)))
}

// ─── Fixture parsing ─────────────────────────────────────────────────────────

#[test]
fn test_parse_bitwig_fixture() {
    let parser = BitwigParser::new(&fixture_path()).expect("fixture should parse");
    assert_eq!(parser.project.track_count, 4);
    assert_eq!(parser.project.tracks.len(), 4);
}

#[test]
fn test_bitwig_track_names() {
    let parser = BitwigParser::new(&fixture_path()).expect("fixture should parse");
    let names: Vec<&str> = parser
        .project
        .tracks
        .iter()
        .map(|t| t.name.as_str())
        .collect();
    assert_eq!(names, vec!["Drums", "Bass", "Keys", "Vox"]);
}

#[test]
fn test_bitwig_track_type_from_attribute() {
    // Bitwig puts the channel type on the <Track> element itself:
    // <Track Type="Midi" Index="2">
    let parser = BitwigParser::new(&fixture_path()).expect("fixture should parse");
    assert_eq!(parser.project.tracks[0].track_type, "Audio");
    assert_eq!(parser.project.tracks[2].track_type, "Midi");
}

#[test]
fn test_bitwig_device_names() {
    // Devices are named with a Name attribute: <Device Name="EQ Eight" />
    let parser = BitwigParser::new(&fixture_path()).expect("fixture should parse");
    let devs: Vec<&str> = parser.project.tracks[0]
        .devices
        .iter()
        .map(|d| d.name.as_str())
        .collect();
    assert_eq!(devs, vec!["EQ Eight", "Compressor"]);
}

#[test]
fn test_bitwig_devicechain_not_treated_as_device() {
    let parser = BitwigParser::new(&fixture_path()).expect("fixture should parse");
    for track in &parser.project.tracks {
        assert!(
            !track.devices.iter().any(|d| d.name == "DeviceChain"),
            "DeviceChain leaked into device list"
        );
    }
}

#[test]
fn test_bitwig_mute_and_solo() {
    let parser = BitwigParser::new(&fixture_path()).expect("fixture should parse");
    assert!(parser.project.tracks[0].is_muted, "Drums should be muted");
    assert!(!parser.project.tracks[1].is_muted);
    assert!(parser.project.tracks[2].is_solo, "Keys should be soloed");
}

#[test]
fn test_bitwig_locators() {
    let parser = BitwigParser::new(&fixture_path()).expect("fixture should parse");
    assert_eq!(parser.project.markers.len(), 3);
    assert_eq!(parser.project.markers[0].name, "Intro");
    assert_eq!(parser.project.markers[0].time, "1.1.1");
}

#[test]
fn test_bitwig_tempo() {
    let parser = BitwigParser::new(&fixture_path()).expect("fixture should parse");
    assert!((parser.project.bpm - 128.0).abs() < 0.01);
}

#[test]
fn test_bitwig_project_type_is_bitwig() {
    use clavus_core::types::ProjectType;
    let parser = BitwigParser::new(&fixture_path()).expect("fixture should parse");
    assert!(matches!(parser.project.project_type, ProjectType::Bitwig));
}

#[test]
fn test_bitwig_embedded_samples_readable() {
    // The archive contains a samples/ tree alongside project.xml.
    let parser = BitwigParser::new(&fixture_path()).expect("fixture should parse");
    assert!(
        !parser.xml_bytes.is_empty(),
        "project.xml should have been extracted from the archive"
    );
    let xml = String::from_utf8_lossy(&parser.xml_bytes);
    assert!(xml.contains("<Project"));
    assert!(xml.contains("Drums"));
}

#[test]
fn test_bitwig_no_samples_fixture() {
    // A .bwproject without embedded samples still parses fine.
    let parser = BitwigParser::new(&no_samples_path()).expect("fixture should parse");
    assert_eq!(parser.project.track_count, 4);
}

// ─── Error handling / fuzzing ───────────────────────────────────────────────

#[test]
fn test_nonexistent_file_returns_error() {
    let result = BitwigParser::new(Path::new("/nonexistent/path.bwproject"));
    assert!(result.is_err(), "nonexistent file should return an error");
}

#[test]
fn test_not_a_zip_returns_error() {
    let tmp = temp_path("clavus_bw_notazip");
    std::fs::write(&tmp, b"this is definitely not a zip archive").unwrap();
    let result = BitwigParser::new(&tmp);
    let _ = std::fs::remove_file(&tmp);
    assert!(result.is_err(), "non-zip should return an error, not panic");
}

#[test]
fn test_empty_file_returns_error() {
    let tmp = temp_path("clavus_bw_empty");
    std::fs::write(&tmp, b"").unwrap();
    let result = BitwigParser::new(&tmp);
    let _ = std::fs::remove_file(&tmp);
    assert!(result.is_err(), "empty file should return an error");
}

#[test]
fn test_zip_without_project_xml_returns_error() {
    // A valid ZIP, but no project.xml inside.
    let tmp = temp_path("clavus_bw_noproject");
    {
        use zip::write::SimpleFileOptions;
        use zip::ZipWriter;
        let file = std::fs::File::create(&tmp).unwrap();
        let mut zw = ZipWriter::new(file);
        zw.start_file("readme.txt", SimpleFileOptions::default()).unwrap();
        std::io::Write::write_all(&mut zw, b"nothing useful here").unwrap();
        zw.finish().unwrap();
    }
    let result = BitwigParser::new(&tmp);
    let _ = std::fs::remove_file(&tmp);
    assert!(
        result.is_err(),
        "zip without project.xml should return an error"
    );
}

#[test]
fn test_truncated_zip_returns_error() {
    let bytes = std::fs::read(fixture_path()).unwrap();
    let tmp = temp_path("clavus_bw_truncated");
    // Keep the first half — the central directory is gone, so it must fail.
    std::fs::write(&tmp, &bytes[..bytes.len() / 2]).unwrap();
    let result = BitwigParser::new(&tmp);
    let _ = std::fs::remove_file(&tmp);
    assert!(result.is_err(), "truncated zip should return an error");
}

#[test]
fn test_corrupt_zip_bytes_returns_error() {
    let mut bytes = std::fs::read(fixture_path()).unwrap();
    // Flip bytes in the middle of the archive.
    for i in (bytes.len() / 3)..(bytes.len() / 3 + 64) {
        bytes[i] = bytes[i].wrapping_add(0xFF);
    }
    let tmp = temp_path("clavus_bw_corrupt");
    std::fs::write(&tmp, &bytes).unwrap();
    let result = BitwigParser::new(&tmp);
    let _ = std::fs::remove_file(&tmp);
    // Must not panic; Err is fine, and so is Ok if the corruption is benign.
    let _ = result;
}

#[test]
fn test_binary_garbage_returns_error() {
    let tmp = temp_path("clavus_bw_binary");
    std::fs::write(&tmp, vec![0x00u8, 0xFF, 0xFE, 0x42, 0x00, 0x7F, 0x80]).unwrap();
    let result = BitwigParser::new(&tmp);
    let _ = std::fs::remove_file(&tmp);
    assert!(result.is_err(), "binary garbage should return an error");
}

#[test]
fn test_project_xml_with_invalid_utf8_returns_error() {
    // Valid ZIP, but project.xml contains invalid UTF-8.
    let tmp = temp_path("clavus_bw_badutf8");
    {
        use zip::write::SimpleFileOptions;
        use zip::ZipWriter;
        let file = std::fs::File::create(&tmp).unwrap();
        let mut zw = ZipWriter::new(file);
        zw.start_file("project.xml", SimpleFileOptions::default()).unwrap();
        std::io::Write::write_all(&mut zw, &[0xFF, 0xFE, 0x00, 0x01, 0x80, 0x81]).unwrap();
        zw.finish().unwrap();
    }
    let result = BitwigParser::new(&tmp);
    let _ = std::fs::remove_file(&tmp);
    assert!(
        result.is_err(),
        "invalid UTF-8 in project.xml should return an error, not panic"
    );
}

#[test]
fn test_malformed_xml_in_project_xml_does_not_panic() {
    // Valid ZIP, project.xml is not well-formed XML.
    let tmp = temp_path("clavus_bw_badxml");
    {
        use zip::write::SimpleFileOptions;
        use zip::ZipWriter;
        let file = std::fs::File::create(&tmp).unwrap();
        let mut zw = ZipWriter::new(file);
        zw.start_file("project.xml", SimpleFileOptions::default()).unwrap();
        std::io::Write::write_all(&mut zw, b"<Project><Tracks><Track></Project>").unwrap();
        zw.finish().unwrap();
    }
    let result = BitwigParser::new(&tmp);
    let _ = std::fs::remove_file(&tmp);
    // The key assertion: it must not panic.
    let _ = result;
}

#[test]
fn test_nested_project_xml_path_is_found() {
    // Some Bitwig versions nest project.xml inside a folder in the archive.
    let tmp = temp_path("clavus_bw_nested");
    {
        use zip::write::SimpleFileOptions;
        use zip::ZipWriter;
        let file = std::fs::File::create(&tmp).unwrap();
        let mut zw = ZipWriter::new(file);
        zw.start_file("MyProject/project.xml", SimpleFileOptions::default())
            .unwrap();
        std::io::Write::write_all(
            &mut zw,
            b"<Project><Tracks><Track Type=\"Audio\"><Name Value=\"X\"/></Track></Tracks></Project>",
        )
        .unwrap();
        zw.finish().unwrap();
    }
    let result = BitwigParser::new(&tmp);
    let _ = std::fs::remove_file(&tmp);
    let parser = result.expect("nested project.xml should be found");
    assert_eq!(parser.project.track_count, 1);
    assert_eq!(parser.project.tracks[0].name, "X");
}
